-- Idempotent migration: widen category CHECK constraints to match UI options
-- and seed any missing master catalog scholarships without overwriting existing DB data.

ALTER TABLE public.profiles DROP CONSTRAINT IF EXISTS profiles_category_check;
ALTER TABLE public.profiles ADD CONSTRAINT profiles_category_check
  CHECK (category IS NULL OR category IN ('General','OBC','SC','ST','EWS','Minority','PwD'));

ALTER TABLE public.applications DROP CONSTRAINT IF EXISTS applications_category_check;
ALTER TABLE public.applications ADD CONSTRAINT applications_category_check
  CHECK (category IN ('General','OBC','SC','ST','EWS','Minority','PwD'));

ON CONFLICT (id) DO NOTHING;
